一、 動態煞車警示燈控制程式 
----------------------------------------------------------------------------------------------- 
#include <reg51.h> 
sbit INTR=P3^3; 

sbit LED=P0^0; 

unsigned char xdata adc; 
unsigned char _adc; 
unsigned char disp[4]={0,1,6,8}; 
unsigned char _adc; 
unsigned char led; 
unsigned int RES; 
void dataproc(unsigned char); 
void delay(int); 
void delay1ms(int); 

main() 
{ 

 while(1) 

 { 

if ((RES<255)&&(RES>210)) 

{led=0;} 


else if ((RES<=219)&&(RES>209)) 

{led=1; 

LED=~LED; 

delay1ms(300);} 


 else if ((RES<208)&&(RES>190)) 

{led=1; 

 LED=~LED; 

 delay1ms(200);} 



else if ((RES<180)&&(RES>1)) 

{LED=1; 

LED=~LED; 

delay1ms(30);} 

 //P1=~led; 
 //delay1ms(1); 
 /*P1=~P1; 
 delay1ms(500);*/ 


 _adc=adc; 
 adc=0xff; 
 while(INTR==1); 
 _adc=adc; 
 dataproc(_adc); 

 } 
} 
void dataproc(unsigned char data_in) 
{int results; 
 results=data_in*2; 
 RES=results; 

} 

void delay1ms(int x) 
{int i,j; 
 for(i=0;i<x;i++) 
 for(j=0;j<120;j++); 
} 
